refentry.refsect1:
&reftitle.description;
mixedarray_find arrayarray callablecallback
array_find restituisce il valore del primo elemento di un &array; per il quale la callback fornita restituisce &true;. Se non viene trovato alcun elemento corrispondente la funzione restituisce &null;.

  &reftitle.examples;

   Esempio di array_find


<?php
$array = [
    'a' => 'dog',
    'b' => 'cat',
    'c' => 'cow',
    'd' => 'duck',
    'e' => 'goose',
    'f' => 'elephant'
];

// Trova il primo animale con un nome più lungo di 4 caratteri.
var_dump(array_find($array, function (string $value) {
    return strlen($value) > 4;
}));

// Trova il primo animale il cui nome inizia con f.
var_dump(array_find($array, function (string $value) {
    return str_starts_with($value, 'f');
}));

// Trova il primo animale la cui chiave dell'array è la prima lettera dell'animale.
var_dump(array_find($array, function (string $value, $key) {
   return $value[0] === $key;
}));

// Trova il primo animale la cui chiave dell'array corrisponde a un'espressione regolare.
var_dump(array_find($array, function ($value, $key) {
   return preg_match('/^([a-f])$/', $key);
}));
?>


   &example.outputs;


string(5) "goose"
NULL
string(3) "cow"
string(3) "dog"
